typedef struct { ParseFn prefix, infix; Precedence prec; } ParseRule;
static ParseRule rules[] = {
  [TOK_MINUS]  = {unary,    binary, PREC_TERM},
  [TOK_LPAREN] = {grouping, call,   PREC_CALL} };
static Expr *parse_precedence(Precedence min) {
  Expr *left = get_rule(advance().type)->prefix();   /* null denotation */
  while (min <= get_rule(peek().type)->prec) {       /* left denotation */
    Token op = advance();
    left = get_rule(op.type)->infix(left);
  }
  return left;
}
